sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var reasonCode = current.reason_code.reason_code.toString();
    var sourceSystem = current.source_system.toString();
	var updateSourceSystemTime = current.source_system_timestamp.toString(); // MSSCUSTODY-5744

    var auditObject = {
        "eventStatusCore": current.trade_lifecycle_status.getDisplayValue(),
        "eventStatusStock": current.trade_cash_stock_status.getDisplayValue(),
        "legacyStatus": current.legacy_status.getDisplayValue(),
        "legacySubStatus": current.legacy_sub_status.getDisplayValue(),
        "reasonCode": reasonCode,
        "cashHoldIndicator": current.cash_hold_indicator.getDisplayValue(),
        "scriptHoldIndicator": current.script_hold_indicator.getDisplayValue(),
        "gdiIndicator": current.gdi_indicator.getDisplayValue(),
        "sourceSystem": sourceSystem,
		"sourceSystemTimestamp": updateSourceSystemTime,
        "reasondescription": current.reason_description_remarks_unex.getDisplayValue(),
        "reasonCacndescription": current.reason_description_remarks_unex.getDisplayValue()
    };

    if (current.u_audit_history) {
        tradeAudExist = JSON.parse(current.u_audit_history);
    } else {
        tradeAudExist = [];
    }
    tradeAudExist.push(auditObject);
    current.u_audit_history = JSON.stringify(tradeAudExist);

})(current, previous);
